// Callback for Start button
static void start_btn_cb(lv_event_t * e)
{
     ESP_LOGI(TAG, "START button pressed");
    esc_start_motor();
    
    // Update UI
    lv_label_set_text(label_status, "Starting...");
}

// Callback for Stop button
static void stop_btn_cb(lv_event_t * e)
{
    ESP_LOGI(TAG, "STOP button pressed");
    esc_stop_motor();
    
    // Update UI
    lv_label_set_text(label_status, "Stopping...");
}

// Callback for Arm button
static void arm_btn_cb(lv_event_t * e)
{
    ESP_LOGI(TAG, "ARM button pressed");
    esc_arm();
    lv_label_set_text(label_status, "ESC Armed");
    lv_label_set_text_fmt(label_target_rpm, "Target: 0 RPM");
}

static void plus_btn_cb(lv_event_t * e)
{
    ESP_LOGI(TAG, "+ button pressed");
    esc_increase_target(100);
    lv_label_set_text_fmt(label_target_rpm, "Target: %lu RPM", esc_get_target_rpm());

}

static void minus_btn_cb(lv_event_t * e)
{
    ESP_LOGI(TAG, "- button pressed");
    esc_decrease_target(100);
    lv_label_set_text_fmt(label_target_rpm, "Target: %lu RPM", esc_get_target_rpm());

}

static void plus2_btn_cb(lv_event_t * e)
{
    ESP_LOGI(TAG, "++ button pressed");
    esc_increase_target(1000);
    lv_label_set_text_fmt(label_target_rpm, "Target: %lu RPM", esc_get_target_rpm());

}

static void minus2_btn_cb(lv_event_t * e)
{
    ESP_LOGI(TAG, "-- button pressed");
    esc_decrease_target(1000);
    lv_label_set_text_fmt(label_target_rpm, "Target: %lu RPM", esc_get_target_rpm());

}
