static void ui_update_task(void *pvParameters)
{
    while (1) {
        // Update current RPM display
        lv_label_set_text_fmt(label_current_rpm, "Current: %lu RPM", esc_get_current_rpm());
        
        // Update status
        if (esc_is_transitioning()) {
            lv_label_set_text(label_status, "Transitioning...");
        } else if (esc_get_current_rpm() > 0) {
            lv_label_set_text_fmt(label_status, "Running at %lu RPM", esc_get_current_rpm());
        } else {
            lv_label_set_text(label_status, "Motor Stopped");
        }
        
        vTaskDelay(pdMS_TO_TICKS(200));  // Update every 200ms
    }
}

