static void splash_timer_cb(lv_timer_t * timer)
{
    lv_disp_t *disp = (lv_disp_t *)timer->user_data;
    
    // Delete splash screen
    lv_obj_del(splash_screen);
    
    // Create main UI
    create_main_ui(disp);
    
    // Delete this timer
    lv_timer_del(timer);
}

void example_lvgl_demo_ui(lv_disp_t *disp)
{
    lv_obj_t *scr = lv_disp_get_scr_act(disp);
    lv_disp_set_rotation(disp,  LV_DISP_ROT_90);
    
    // Create splash screen with background
    splash_screen = lv_obj_create(scr);
    lv_obj_set_size(splash_screen, LV_HOR_RES, LV_VER_RES);
    lv_obj_center(splash_screen);
    lv_obj_clear_flag(splash_screen, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_color(splash_screen, lv_color_white(), 0);
    
    // Create image on splash screen
    lv_obj_t * img = lv_img_create(splash_screen);
    lv_img_set_src(img, &my_image);
    lv_obj_center(img);
    
    // Optional: Add a label below the image
    lv_obj_t * label = lv_label_create(splash_screen);
    lv_label_set_text(label, "Loading...");
    lv_obj_align(label, LV_ALIGN_BOTTOM_MID, 0, -20);
    lv_obj_set_style_text_color(label, lv_color_black(), 0);
    
    // Show splash for 3 seconds, then show main UI
    lv_timer_create(splash_timer_cb, 3000, disp);
}